//! The MCP tools and their parameter and result types.
//!
//! Every read tool reads paperstore directly and resolves an unversioned
//! paper id to its latest stored revision. Unknown papers, malformed ids,
//! invalid line ranges and mismatched revisions come back as MCP tool
//! errors carrying the error message.

// The `ServerHandler` impl generated by `tool_router(server_handler)` has
// async methods that never await, and an allow on the impl block does not
// reach it.
#![allow(clippy::unused_async_trait_impl)]

use paperstore::{PaperNum, PaperRow, StorageBackend};
use rmcp::handler::server::wrapper::{Json, Parameters};
use rmcp::{tool, tool_router};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use similar::TextDiff;

use super::PaperServer;
use crate::chunk::{Section, outline};
use crate::error::Error;
use crate::lines::slice_lines;
use crate::selection::resolve_latest;

/// Lines of unchanged context around each change in a diff.
const DIFF_CONTEXT_LINES: usize = 3;

/// Names one paper.
#[derive(Debug, Deserialize, JsonSchema)]
pub struct PaperIdParams {
    /// Paper id such as `P2300R10`, or `P2300` for the latest revision.
    pub paper_id: String,
}

/// Names a paper and a range of its lines.
#[derive(Debug, Deserialize, JsonSchema)]
pub struct PaperLinesParams {
    /// Paper id such as `P2300R10`, or `P2300` for the latest revision.
    pub paper_id: String,
    /// First line, 1-based and inclusive; negative counts from the end
    /// (`-1` is the last line). Defaults to the first line. Never 0.
    #[serde(default)]
    pub start: Option<i64>,
    /// Line after the range, 1-based and exclusive; negative counts from the
    /// end. Defaults to past the last line. At least one bound is required.
    #[serde(default)]
    pub end: Option<i64>,
}

/// Names two revisions of one paper.
#[derive(Debug, Deserialize, JsonSchema)]
pub struct DiffParams {
    /// The older revision, such as `P2300R9`.
    pub from_id: String,
    /// The newer revision, such as `P2300R10`, or `P2300` for the latest.
    pub to_id: String,
}

/// A range of a paper's lines.
#[derive(Debug, Serialize, JsonSchema)]
pub struct PaperLines {
    /// The resolved paper id.
    pub paper_id: String,
    /// First returned line, 1-based and inclusive.
    pub start: usize,
    /// Line after the last returned line, 1-based and exclusive.
    pub end: usize,
    /// Number of lines in the whole paper.
    pub total_lines: usize,
    /// The lines, joined with `\n`.
    pub text: String,
}

/// Every paperstore metadata field of one paper.
#[derive(Debug, Serialize, JsonSchema)]
pub struct PaperMetadata {
    /// The resolved paper id.
    pub paper_id: String,
    /// Mailing year.
    pub year: String,
    /// Paper title.
    pub title: String,
    /// Author names.
    pub authors: Vec<String>,
    /// Target subgroup.
    pub target_group: String,
    /// Intent signal from conversion.
    pub intent: String,
    /// Canonical URL.
    pub url: String,
    /// Document date.
    pub document_date: String,
    /// Mailing date (`YYYY-MM`).
    pub mailing_date: String,
    /// Disposition.
    pub disposition: String,
    /// Previous revision's paper id, or empty.
    pub previous_version: String,
    /// Staged source file path, or empty.
    pub source_file: String,
    /// Converted Markdown path, or empty.
    pub markdown_path: String,
    /// Deprecated dissect artifact path, or empty.
    pub dissect_path: String,
    /// Agora artifact path, or empty.
    pub agora_path: String,
    /// Assay report path, or empty.
    pub assay_path: String,
    /// Time of the last citation extraction, or empty.
    pub citations_extracted_at: String,
    /// Last recorded pipeline error, or empty.
    pub error: String,
    /// Line count of the converted Markdown.
    pub line_count: u64,
    /// Pipeline status code.
    pub status: i64,
}

impl From<PaperRow> for PaperMetadata {
    fn from(row: PaperRow) -> Self {
        Self {
            paper_id: row.paper_num,
            year: row.year,
            title: row.title,
            authors: row.authors,
            target_group: row.target_group,
            intent: row.intent,
            url: row.url,
            document_date: row.document_date,
            mailing_date: row.mailing_date,
            disposition: row.disposition,
            previous_version: row.previous_version,
            source_file: row.source_file,
            markdown_path: row.markdown_path,
            dissect_path: row.dissect_path,
            agora_path: row.agora_path,
            assay_path: row.assay_path,
            citations_extracted_at: row.citations_extracted_at,
            error: row.error,
            line_count: row.line_count,
            status: row.status,
        }
    }
}

/// One stored revision of a paper.
#[derive(Debug, Serialize, JsonSchema)]
pub struct Revision {
    /// The revision's paper id.
    pub paper_id: String,
    /// Document date.
    pub date: String,
    /// Mailing date (`YYYY-MM`).
    pub mailing: String,
    /// Previous revision's paper id, or empty.
    pub previous_version: String,
}

/// Every stored revision of a paper.
#[derive(Debug, Serialize, JsonSchema)]
pub struct Revisions {
    /// Revisions, newest first.
    pub revisions: Vec<Revision>,
}

/// One heading of a paper and the lines it governs.
#[derive(Debug, Serialize, JsonSchema)]
pub struct OutlineSection {
    /// Heading level, 1 to 6.
    pub level: usize,
    /// Heading text.
    pub heading: String,
    /// The heading's line, 1-based and inclusive.
    pub start: usize,
    /// The next heading at the same or a higher level, or one past the
    /// last line, 1-based and exclusive.
    pub end: usize,
}

impl From<Section> for OutlineSection {
    fn from(section: Section) -> Self {
        Self {
            level: section.level,
            heading: section.heading,
            start: section.start,
            end: section.end,
        }
    }
}

/// A paper's heading outline.
#[derive(Debug, Serialize, JsonSchema)]
pub struct Outline {
    /// The resolved paper id.
    pub paper_id: String,
    /// Headings in document order.
    pub sections: Vec<OutlineSection>,
}

/// Parses `raw` and resolves it to a stored revision.
fn resolve_id(store: &dyn StorageBackend, raw: &str) -> crate::error::Result<PaperNum> {
    resolve_latest(store, &PaperNum::parse(raw)?)
}

fn read_paper(store: &dyn StorageBackend, raw: &str) -> crate::error::Result<String> {
    let num = resolve_id(store, raw)?;
    Ok(store.paper_md(&num)?)
}

fn read_lines(
    store: &dyn StorageBackend,
    params: &PaperLinesParams,
) -> crate::error::Result<PaperLines> {
    let num = resolve_id(store, &params.paper_id)?;
    let slice = slice_lines(&store.paper_md(&num)?, params.start, params.end)?;
    Ok(PaperLines {
        paper_id: num.to_string(),
        start: slice.start,
        end: slice.end,
        total_lines: slice.total_lines,
        text: slice.text,
    })
}

fn read_metadata(store: &dyn StorageBackend, raw: &str) -> crate::error::Result<PaperMetadata> {
    let num = resolve_id(store, raw)?;
    Ok(store.meta(&num)?.into())
}

fn read_revisions(store: &dyn StorageBackend, raw: &str) -> crate::error::Result<Revisions> {
    let num = PaperNum::parse(raw)?;
    let rows = store.list_revisions(&num)?;
    if rows.is_empty() {
        return Err(paperstore::Error::missing_paper(num).into());
    }
    let revisions = rows
        .into_iter()
        .map(|row| Revision {
            paper_id: row.paper_num,
            date: row.document_date,
            mailing: row.mailing_date,
            previous_version: row.previous_version,
        })
        .collect();
    Ok(Revisions { revisions })
}

fn read_outline(store: &dyn StorageBackend, raw: &str) -> crate::error::Result<Outline> {
    let num = resolve_id(store, raw)?;
    let md = store.paper_md(&num)?;
    Ok(Outline {
        paper_id: num.to_string(),
        sections: outline(&md).into_iter().map(OutlineSection::from).collect(),
    })
}

fn read_diff(store: &dyn StorageBackend, params: &DiffParams) -> crate::error::Result<String> {
    let from = PaperNum::parse(&params.from_id)?;
    let to = PaperNum::parse(&params.to_id)?;
    if from.split_revision().0 != to.split_revision().0 {
        return Err(Error::RevisionMismatch { from, to });
    }
    let from = resolve_latest(store, &from)?;
    let to = resolve_latest(store, &to)?;
    let old = store.paper_md(&from)?;
    let new = store.paper_md(&to)?;
    Ok(TextDiff::from_lines(&old, &new)
        .unified_diff()
        .context_radius(DIFF_CONTEXT_LINES)
        .header(from.as_str(), to.as_str())
        .to_string())
}

// The macro expansion names a bare `Result`, so this module does not
// import the crate's `Result` alias.
#[tool_router(server_handler)]
impl PaperServer {
    #[tool(
        description = "Return the full Markdown of a paper, uncapped. An unversioned id such as P2300 resolves to the latest revision."
    )]
    async fn get_paper(
        &self,
        Parameters(params): Parameters<PaperIdParams>,
    ) -> Result<String, String> {
        self.read(move |store| read_paper(store, &params.paper_id))
            .await
    }

    #[tool(
        description = "Return a range of a paper's Markdown lines. Lines are 1-based; start is inclusive and end exclusive, negative bounds count from the end like Python slices, and out-of-range bounds are clamped. Give start, end or both."
    )]
    async fn get_paper_lines(
        &self,
        Parameters(params): Parameters<PaperLinesParams>,
    ) -> Result<Json<PaperLines>, String> {
        self.read(move |store| read_lines(store, &params))
            .await
            .map(Json)
    }

    #[tool(description = "Return every paperstore metadata field of a paper.")]
    async fn get_paper_metadata(
        &self,
        Parameters(params): Parameters<PaperIdParams>,
    ) -> Result<Json<PaperMetadata>, String> {
        self.read(move |store| read_metadata(store, &params.paper_id))
            .await
            .map(Json)
    }

    #[tool(
        description = "List every stored revision of a paper, newest first, with document date, mailing and previous version. Any revision's id, or the unversioned id, names the paper."
    )]
    async fn list_revisions(
        &self,
        Parameters(params): Parameters<PaperIdParams>,
    ) -> Result<Json<Revisions>, String> {
        self.read(move |store| read_revisions(store, &params.paper_id))
            .await
            .map(Json)
    }

    #[tool(
        description = "Return a paper's heading outline: each heading's level, text and line range (1-based, end exclusive), usable with get_paper_lines."
    )]
    async fn get_paper_outline(
        &self,
        Parameters(params): Parameters<PaperIdParams>,
    ) -> Result<Json<Outline>, String> {
        self.read(move |store| read_outline(store, &params.paper_id))
            .await
            .map(Json)
    }

    #[tool(
        description = "Return a unified diff, uncapped, between the Markdown of two revisions of the same paper. An unversioned id resolves to the latest revision."
    )]
    async fn diff_revisions(
        &self,
        Parameters(params): Parameters<DiffParams>,
    ) -> Result<String, String> {
        self.read(move |store| read_diff(store, &params)).await
    }
}
